python3 - <<'E'
import re
s=open('app.ts').read()
helper='''async function assertBankAccountNotLinked(
  syncSource: string,
  providerAccountId: string,
  upgradingId?: string,
) {
  const existing = await db.first<Pick<db.DbAccount, 'id'>>(
    `SELECT id FROM accounts
     WHERE tombstone = 0 AND account_sync_source = ? AND account_id = ? AND id IS NOT ?`,
    [syncSource, providerAccountId, upgradingId ?? null],
  );
  if (existing) {
    throw new Error('This bank account is already linked to another account.');
  }
}

'''
s=s.replace('async function linkGoCardlessAccount(',helper+'async function linkGoCardlessAccount(',1)
for fn,src,var in [('linkGoCardlessAccount','goCardless','account'),('linkSimpleFinAccount','simpleFin','externalAccount'),('linkPluggyAiAccount','pluggyai','externalAccount'),('linkAkahuAccount','akahu','externalAccount'),('linkEnableBankingAccount','enableBanking','externalAccount')]:
    i=s.index('async function %s('%fn)
    j=s.index('\n}: LinkAccountBaseParams',i)
    k=s.index('{\n',j)+2
    s=s[:k]+"  await assertBankAccountNotLinked(\n    '%s',\n    %s.account_id,\n    upgradingId,\n  );\n"%(src,var)+s[k:]
open('app.ts','w').write(s)
E
